package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_html_TriageGen1Test {

    @Test
    public void testHtml_BuildsCorrectHtmlString() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create());

        // When
        String htmlString = element.html();

        // Then
        assertEquals("<div></div>", htmlString);
    }

    @Test
    public void testHtml_IgnoresEmptyStringBuilder() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create());

        // When
        element.html(new StringBuilder());

        // Then
        assertEquals("", element.html());
    }

    @Test
    public void testHtml_BuildsCorrectHtmlString_WithTagName() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create());

        // When
        element.tagName("span");

        // Then
        assertEquals("<span></span>", element.html());
    }

    @Test
    public void testHtml_BuildsCorrectHtmlString_WithAttributes() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create().attr("id", "my-id"));

        // When
        String htmlString = element.html();

        // Then
        assertEquals("<div id=\"my-id\"></div>", htmlString);
    }

    @Test
    public void testHtml_BuildsCorrectHtmlString_WithChildren() {
        // Given
        Element parent = new Element(Tag.valueOf("div"), "", Attributes.create());
        Element child = new Element(Tag.valueOf("p"), "", Attributes.create());
        parent.appendChild(child);

        // When
        String htmlString = parent.html();

        // Then
        assertEquals("<div><p></p></div>", htmlString);
    }

    @Test
    public void testHtml_BuildsCorrectHtmlString_WithText() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create());
        element.appendText("Hello, World!");

        // When
        String htmlString = element.html();

        // Then
        assertEquals("<div>Hello, World!</div>", htmlString);
    }

    @Test
    public void testHtml_BuildsCorrectHtmlString_WithWhitespace() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create());
        element.append("   ");

        // When
        String htmlString = element.html();

        // Then
        assertEquals("<div>   </div>", htmlString);
    }

    @Test
    public void testHtml_BuildsCorrectHtmlString_WithNull() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create());

        // When
        String htmlString = element.html();

        // Then
        assertEquals("<div></div>", htmlString);
    }

    @Test
    public void testHtml_BuildsCorrectHtmlString_WithEmptyString() {
        // Given
        Element element = new Element(Tag.valueOf("div"), "", Attributes.create());

        // When
        String htmlString = element.html();

        // Then
        assertEquals("<div></div>", htmlString);
    }
}
